def brute_optimum(starts, hops, bursts, C, hit, miss, dec, fixed=0):
    """Exact minimum (work, image_pages) over every legal layout of one version."""
    frontier = version_frontier(starts, hops, bursts, C, hit, miss, dec)
    best = None
    for work, pages, resident in frontier:
        cand = (work, pages + fixed)
        if best is None or cand < best:
            best = cand
    return best


def brute_case(frontiers, C, hit, miss, dec, fixed_list):
    """Exact case optimum with the resident budget shared by all versions."""
    best = [None]

    def rec(idx, used, work, pages):
        if best[0] is not None and (work, pages) > best[0]:
            return
        if idx == len(frontiers):
            if best[0] is None or (work, pages) < best[0]:
                best[0] = (work, pages)
            return
        for w, p, r in frontiers[idx]:
            if used + r <= C:
                rec(idx + 1, used + r, work + w, pages + p + fixed_list[idx])

    rec(0, 0, 0, 0)
    return best[0]


def version_frontier(starts, hops, bursts, C, hit, miss, dec):
    """Pareto frontier of (work, pages, resident) over all layouts."""
    R = len(starts)
    R = len(starts)
